"""Modern migration of the Meridian CRM order-total recomputation job."""

from decimal import Decimal, ROUND_HALF_UP, localcontext


_CENTS = Decimal("0.01")


def _decimal(value: object) -> Decimal:
    """Convert supported numeric input values using decimal-safe semantics."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Decimal("0")
    return Decimal(str(value))


def _precision(values: list[Decimal]) -> int:
    """Provide enough working precision for products, sums, and quantization."""
    return max(28, sum(len(value.as_tuple().digits) for value in values) + 20)


def recompute(order: dict, lines: list[dict]) -> tuple[dict, list[dict], list]:
    """Recompute one eligible order's live line extensions and discounted total."""
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    parsed_lines: list[tuple[Decimal, Decimal] | None] = []
    working_values: list[Decimal] = [Decimal("100")]

    for line in lines:
        if line.get("DEL_FLG") == "Y":
            parsed_lines.append(None)
            continue

        quantity = _decimal(line.get("QTY", 0))
        unit_price = _decimal(line.get("UNIT_PRC", 0))
        parsed_lines.append((quantity, unit_price))
        working_values.extend((quantity, unit_price))

    discount = _decimal(order.get("DISC_PCT", 0))
    incoming_total = _decimal(order.get("TOT_AMT", 0))
    working_values.extend((discount, incoming_total))

    with localcontext() as context:
        context.prec = _precision(working_values)
        total = Decimal("0")

        for index, parsed in enumerate(parsed_lines):
            if parsed is None:
                continue

            quantity, unit_price = parsed
            extension = (quantity * unit_price).quantize(
                _CENTS, rounding=ROUND_HALF_UP
            )
            new_lines[index]["EXT_AMT"] = float(extension)
            total += extension

        discounted = (
            total * (Decimal("100") - discount) / Decimal("100")
        ).quantize(_CENTS, rounding=ROUND_HALF_UP)

    new_order["TOT_AMT"] = float(discounted)

    audits = []
    if incoming_total != discounted:
        audits.append(("ORD_RETOTAL", order.get("ORD_ID")))

    return new_order, new_lines, audits
